cd /tmp/sv-72d2d7cbd7854a65b6b2c28104e0ae4a/advanced-multi-complexity && dotnet package list --format json > after-cpm-packages.json 2>/dev/null && python3 -c "
import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def get_packages(data):
    pkgs = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        proj_pkgs = {}
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                key = (pkg['id'], fw['framework'])
                proj_pkgs[key] = pkg['resolvedVersion']
        pkgs[name] = proj_pkgs
    return pkgs

b = get_packages(baseline)
a = get_packages(after)

changes = []
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for key in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(key)
        av = ap.get(key)
        if bv != av:
            changes.append(f'  {proj}: {key[0]} ({key[1]}): {bv} -> {av}')

if changes:
    print('VERSION CHANGES:')
    for c in changes:
        print(c)
else:
    print('No version changes - conversion is version-neutral')
"

